// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  spring,
  interpolate,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');

const { fontFamily: interFamily } = loadInter();



export type AttributionOverlayProps = Record<string, any>;

const AttributionOverlay: React.FC<AttributionOverlayProps> = ({
  backgroundColor = "#080808",
  transparentBackground = true,
  durationInSeconds = 12,
  introTitle = "The User Journey",
  adATitle = "Ad A",
  adARole = "The Awareness Play",
  adBTitle = "Ad B",
  adBRole = "The Consideration Play",
  adCTitle = "Ad C",
  adCRole = "The Call-to-Action",
  conversionText = "User Converts!",
  summaryText = "They all worked together.",
  primaryColor = "#0064e0",
  cardColor = "#1a1a1a",
  textColor = "#ffffff",
  accentColor = "#00a400",
  lineColor = "#333333",
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Safety parsed background
  const bgColor = transparentBackground ? "transparent" : backgroundColor;

  // Timings
  const totalFrames = durationInSeconds * fps;
  const safeOutroStart = Math.max(1, totalFrames - 30);
  const finalTotalFrames = Math.max(safeOutroStart + 1, totalFrames);

  // Global Outro Fades
  const mainOpacity = interpolate(
    frame,
    [safeOutroStart, finalTotalFrames],
    [1, 0],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  // Intro Title Timing
  const introSpring = spring({ frame, fps, config: { damping: 16 } });
  const introY = interpolate(introSpring, [0, 1], [-50, 0]);

  // Steps Configuration - Added 2.5 seconds (75 frames) delay before roles load
  const steps = [
    { title: adATitle, role: adARole, enterFrame: 15, roleFrame: 165, isLast: false },
    { title: adBTitle, role: adBRole, enterFrame: 30, roleFrame: 185, isLast: false },
    { title: adCTitle, role: adCRole, enterFrame: 45, roleFrame: 205, isLast: true },
  ];

  // Conversion Badge Timing
  const conversionSpring = spring({
    frame: frame - 60,
    fps,
    config: { damping: 10, mass: 0.8 },
  });

  // Summary Text Timing - Shifted by the same 75 frames to maintain sequence
  const summarySpring = spring({
    frame: frame - 235,
    fps,
    config: { damping: 14 },
  });

  // Timeline Line Animation
  // Line grows as steps appear, fully drawn by frame 55
  const lineProgress = interpolate(frame, [15, 55], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // Responsive Math
  const paddingX = width * 0.1;
  const dotSize = width * 0.03;
  const lineWidth = dotSize * 0.3;
  const lineLeft = dotSize / 2 - lineWidth / 2;

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        fontFamily: interFamily,
        color: textColor,
        opacity: mainOpacity,
        display: "flex",
        flexDirection: "column",
        alignItems: "center",
        justifyContent: "center",
      }}
    >
      <div
        style={{
          width: width - paddingX * 2,
          height: height * 0.7,
          display: "flex",
          flexDirection: "column",
        }}
      >
        {/* Header Section */}
        <div
          style={{
            opacity: introSpring,
            transform: `translateY(${introY}px)`,
            marginBottom: height * 0.05,
            textAlign: "center",
          }}
        >
          <h1
            style={{
              fontSize: width * 0.06,
              fontWeight: 800,
              margin: 0,
              letterSpacing: "-0.03em",
              color: "rgba(255,255,255,0.9)",
            }}
          >
            {introTitle}
          </h1>
        </div>

        {/* Timeline Section */}
        <div style={{ position: "relative", flex: 1, display: "flex", flexDirection: "column", gap: height * 0.04 }}>
          {/* Animated Timeline Connecting Line */}
          <div
            style={{
              position: "absolute",
              top: dotSize / 2,
              bottom: dotSize / 2,
              left: lineLeft,
              width: lineWidth,
              backgroundColor: lineColor,
              borderRadius: lineWidth,
              transformOrigin: "top center",
              transform: `scaleY(${lineProgress})`,
            }}
          />

          {steps.map((step, index) => {
            const cardSpring = spring({
              frame: frame - step.enterFrame,
              fps,
              config: { damping: 16 },
            });
            const roleSpring = spring({
              frame: frame - step.roleFrame,
              fps,
              config: { damping: 14 },
            });

            const cardX = interpolate(cardSpring, [0, 1], [100, 0]);
            const roleY = interpolate(roleSpring, [0, 1], [20, 0]);

            return (
              <div
                key={index}
                style={{
                  display: "flex",
                  alignItems: "center",
                  opacity: cardSpring,
                  transform: `translateX(${cardX}px)`,
                  position: "relative",
                  zIndex: 2,
                }}
              >
                {/* Timeline Dot */}
                <div
                  style={{
                    width: dotSize,
                    height: dotSize,
                    borderRadius: "50%",
                    backgroundColor: cardSpring > 0.5 ? primaryColor : lineColor,
                    border: `4px solid ${backgroundColor}`,
                    boxShadow: cardSpring > 0.5 ? `0 0 15px ${primaryColor}80` : "none",
                    transition: "none",
                    flexShrink: 0,
                    marginRight: width * 0.05,
                  }}
                />

                {/* Card */}
                <div
                  style={{
                    flex: 1,
                    backgroundColor: cardColor,
                    padding: height * 0.03,
                    borderRadius: width * 0.04,
                    border: `1px solid rgba(255,255,255,0.05)`,
                    position: "relative",
                    display: "flex",
                    flexDirection: "column",
                    justifyContent: "center",
                    boxShadow: "0 20px 40px rgba(0,0,0,0.4)",
                  }}
                >
                  <h2
                    style={{
                      fontSize: width * 0.05,
                      fontWeight: 700,
                      margin: 0,
                    }}
                  >
                    {step.title}
                  </h2>

                  {/* Role Reveal Text */}
                  <p
                    style={{
                      fontSize: width * 0.035,
                      fontWeight: 500,
                      color: primaryColor,
                      margin: 0,
                      marginTop: roleSpring > 0 ? height * 0.01 : 0,
                      opacity: roleSpring,
                      transform: `translateY(${roleY}px)`,
                      height: roleSpring > 0 ? "auto" : 0,
                      overflow: "hidden",
                    }}
                  >
                    {step.role}
                  </p>

                  {/* Conversion Badge on Last Card */}
                  {step.isLast && (
                    <div
                      style={{
                        position: "absolute",
                        top: -height * 0.02,
                        right: -width * 0.04,
                        backgroundColor: accentColor,
                        color: "#000",
                        fontWeight: 800,
                        fontSize: width * 0.035,
                        padding: `${height * 0.01}px ${width * 0.04}px`,
                        borderRadius: width * 0.05,
                        opacity: conversionSpring,
                        transform: `scale(${conversionSpring}) rotate(5deg)`,
                        boxShadow: `0 10px 30px ${accentColor}80`,
                        zIndex: 10,
                      }}
                    >
                      {conversionText}
                    </div>
                  )}
                </div>
              </div>
            );
          })}
        </div>

        {/* Footer / Summary Text */}
        <div
          style={{
            marginTop: height * 0.05,
            opacity: summarySpring,
            transform: `translateY(${interpolate(summarySpring, [0, 1], [30, 0])}px)`,
            textAlign: "center",
            padding: height * 0.03,
            backgroundColor: `${primaryColor}20`,
            borderRadius: width * 0.03,
            border: `1px solid ${primaryColor}40`,
          }}
        >
          <p
            style={{
              fontSize: width * 0.045,
              fontWeight: 600,
              color: "#fff",
              margin: 0,
            }}
          >
            {summaryText}
          </p>
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default AttributionOverlay;